// ================================================================
// WF-ANALYZER V4 - PORT_SCAN + BRUTE_FORCE + DHCP + Metrics
// - BRUTE_FORCE bat theo 2 cach:
//     (a) SSH auth log "Failed password"   (khi port 22 duoc allow)
//     (b) Firewall SYN flood vao 1 port    (khi hydra bi firewall block) <- MOI
// - Dedupe INCIDENT cho ca BanIP lan BanEvent (2 lop)
// - LUU Y: staticData chi persist khi workflow ACTIVE chay bang trigger
// ================================================================

const content = $('Extract Text').first()?.json?.data || '';
const rawLines = content.split(/\r?\n/).map(s => s.trim()).filter(Boolean);

// ---------------- CAU HINH ----------------
const INTERNAL_NETS = ['192.168.10.', '192.168.11.', '192.168.12.', '192.168.20.'];
const IGNORE_PREFIXES = ['169.254.', '224.', '239.', '255.', '0.', '127.'];
const IGNORE_EXACT = ['192.168.183.1', '192.168.10.1'];

const THRESHOLDS = {
  BRUTE_FORCE: { count: 5, window: 60 },     // SSH auth log
  CONN_FLOOD: { count: 8, window: 60 },      // MOI: SYN dồn vào 1 port (hydra bị block)
  PORT_SCAN: { distinctPorts: 15, window: 10 },
};

// Im lang lau hon nguong nay -> incident moi
const INCIDENT_QUIET_MS = { PORT_SCAN: 20000, BRUTE_FORCE: 70000 };

const BAN_FILE_MAP = { PORT_SCAN: 'BanIP_Scanport.txt', BRUTE_FORCE: 'BanIP_Bruteforce.txt' };
const EVENT_FILE_MAP = { PORT_SCAN: 'BanEvent_Scanport.jsonl', BRUTE_FORCE: 'BanEvent_Bruteforce.jsonl' };
const SCENARIO_MAP = { PORT_SCAN: 'BLOCK_SCAN', BRUTE_FORCE: 'BLOCK_BRUTE' };
const EVENT_PREFIX_MAP = { PORT_SCAN: 'SCAN', BRUTE_FORCE: 'BRUTE' };

// ---------------- DHCP ----------------
const DHCP_KEYWORDS = ['DHCPDISCOVER','DHCPREQUEST','DHCPOFFER','DHCPACK','DHCPNAK','DHCPDECLINE','DHCPRELEASE','DHCPINFORM'];
const isDhcpLine = raw => raw.toLowerCase().includes('dhcpd') || DHCP_KEYWORDS.some(k => raw.includes(k));

// ---------------- REGEX ----------------
const RE_ANY_IP = /\b(\d{1,3}(?:\.\d{1,3}){3})\b/g;
const RE_TCP = /,tcp,\d+,(\d{1,3}(?:\.\d{1,3}){3}),(\d{1,3}(?:\.\d{1,3}){3}),(\d+),(\d+),[^,]*,([A-Z]*)/;
const RE_SSH = /Failed password for (?:invalid user )?(\S+) from (\d{1,3}(?:\.\d{1,3}){3}) port (\d+)/;

// ---------------- HELPERS ----------------
const isInternal = ip => Boolean(ip && INTERNAL_NETS.some(net => ip.startsWith(net)));
const shouldIgnore = ip => !ip || IGNORE_EXACT.includes(ip) || IGNORE_PREFIXES.some(p => ip.startsWith(p));
const pickAttacker = (src, dst) => (src && !isInternal(src)) ? src : (dst && !isInternal(dst)) ? dst : (src || dst);

function timestampFromLine(line) {
  const tab = line.indexOf('\t');
  if (tab < 0) return Date.now() / 1000;
  const parsed = Date.parse(line.slice(0, tab).trim());
  return Number.isNaN(parsed) ? Date.now() / 1000 : parsed / 1000;
}

function extractSignal(raw) {
  const lower = raw.toLowerCase();

  // SSH brute force (khi port 22 allow)
  const ssh = raw.match(RE_SSH);
  if (ssh) {
    const ip = ssh[2];
    if (shouldIgnore(ip) || isInternal(ip)) return null;
    return { kind: 'auth_fail', src_ip: ip, dst_port: 22 };
  }

  // pfSense filterlog
  if (!lower.includes('filterlog') || (!lower.includes(',block,') && !lower.includes(',pass,'))) return null;

  const ips = [...raw.matchAll(RE_ANY_IP)].map(m => m[1]);
  if (ips.length < 2) return null;

  const attackerIp = pickAttacker(ips[0], ips[1]);
  if (shouldIgnore(attackerIp) || isInternal(attackerIp)) return null;

  const tcp = raw.match(RE_TCP);
  const dstPort = tcp ? Number.parseInt(tcp[4], 10) : null;
  const flags = tcp?.[5] || null;

  return { kind: flags === 'S' ? 'syn' : 'fw_block', src_ip: attackerIp, dst_port: dstPort };
}

function eventsInWindow(list, refTs, seconds, kinds = null) {
  const allowed = kinds ? new Set(Array.isArray(kinds) ? kinds : [kinds]) : null;
  return list.filter(e => {
    const age = refTs - e.ts;
    return age >= 0 && age <= seconds && (!allowed || allowed.has(e.kind));
  });
}

const countDistinctPorts = list => new Set(list.filter(e => e.port != null).map(e => e.port)).size;

// MOI: port bi đập nhieu nhat -> { port, count }
function topPort(list) {
  const byPort = {};
  for (const e of list) if (e.port != null) byPort[e.port] = (byPort[e.port] || 0) + 1;
  let best = null;
  for (const [port, count] of Object.entries(byPort)) if (!best || count > best.count) best = { port: Number(port), count };
  return best;
}

function countThresholdCrossingMs(list, threshold) {
  if (list.length < threshold) return null;
  const sorted = [...list].sort((a, b) => a.ts - b.ts);
  return Math.round(sorted[threshold - 1].ts * 1000);
}

function distinctPortCrossingMs(list, threshold) {
  const sorted = [...list].sort((a, b) => a.ts - b.ts);
  const ports = new Set();
  for (const e of sorted) {
    if (e.port == null) continue;
    ports.add(e.port);
    if (ports.size >= threshold) return Math.round(e.ts * 1000);
  }
  return null;
}

function latestEventMs(list) {
  let latest = null;
  for (const e of list) {
    if (!Number.isFinite(e.ts)) continue;
    const ms = Math.round(e.ts * 1000);
    if (latest === null || ms > latest) latest = ms;
  }
  return latest;
}

// ---------------- PARSE LOG ----------------
const securityEventsByIp = {};
const dhcpLines = [];
let referenceTimestamp = 0;

for (const line of rawLines) {
  const tab = line.indexOf('\t');
  const raw = tab >= 0 ? line.slice(tab + 1) : line;
  const ts = timestampFromLine(line);
  if (ts > referenceTimestamp) referenceTimestamp = ts;

  if (isDhcpLine(raw)) { dhcpLines.push(line); continue; }

  const signal = extractSignal(raw);
  if (!signal) continue;

  (securityEventsByIp[signal.src_ip] ||= []).push({ ts, port: signal.dst_port, kind: signal.kind });
}

if (!referenceTimestamp) referenceTimestamp = Date.now() / 1000;

// ---------------- DETECT ----------------
const analyzerDetectedAtMs = Date.now();  // T1
const analyzerDetectedAt = new Date(analyzerDetectedAtMs).toISOString();
const detections = [];

for (const [ip, eventList] of Object.entries(securityEventsByIp)) {
  let finding = null;

  // (a) BRUTE FORCE - SSH auth log
  const authEvents = eventsInWindow(eventList, referenceTimestamp, THRESHOLDS.BRUTE_FORCE.window, 'auth_fail');
  if (authEvents.length >= THRESHOLDS.BRUTE_FORCE.count) {
    finding = {
      type: 'BRUTE_FORCE',
      metric: authEvents.length,
      source_event_at_ms: countThresholdCrossingMs(authEvents, THRESHOLDS.BRUTE_FORCE.count),
      _last_signal_at_ms: latestEventMs(authEvents),
    };
  }

  // (b) BRUTE FORCE - firewall SYN flood vao 1 port (hydra bị block) <- MOI
  if (!finding) {
    const connEvents = eventsInWindow(eventList, referenceTimestamp, THRESHOLDS.CONN_FLOOD.window, ['syn', 'fw_block']);
    const distinct = countDistinctPorts(connEvents);
    const top = topPort(connEvents);
    // Chi tinh la brute khi don vao 1 port (distinct < nguong scan), khong phai quet nhieu port
    if (top && top.count >= THRESHOLDS.CONN_FLOOD.count && distinct < THRESHOLDS.PORT_SCAN.distinctPorts) {
      const portEvents = connEvents.filter(e => e.port === top.port);
      finding = {
        type: 'BRUTE_FORCE',
        metric: top.count,
        source_event_at_ms: countThresholdCrossingMs(portEvents, THRESHOLDS.CONN_FLOOD.count),
        _last_signal_at_ms: latestEventMs(connEvents),
      };
    }
  }

  // PORT SCAN
  if (!finding) {
    const scanEvents = eventsInWindow(eventList, referenceTimestamp, THRESHOLDS.PORT_SCAN.window, ['syn', 'fw_block']);
    const distinctPorts = countDistinctPorts(scanEvents);
    if (distinctPorts >= THRESHOLDS.PORT_SCAN.distinctPorts) {
      finding = {
        type: 'PORT_SCAN',
        metric: distinctPorts,
        source_event_at_ms: distinctPortCrossingMs(scanEvents, THRESHOLDS.PORT_SCAN.distinctPorts),
        _last_signal_at_ms: latestEventMs(scanEvents),
      };
    }
  }

  if (!finding) continue;

  const srcMs = Number(finding.source_event_at_ms);
  detections.push({
    src_ip: ip,
    event_type: finding.type,
    metric: finding.metric,
    source_event_at_ms: Number.isFinite(srcMs) ? srcMs : null,                              // T0
    source_event_at: Number.isFinite(srcMs) ? new Date(srcMs).toISOString() : null,
    analyzer_detected_at_ms: analyzerDetectedAtMs,                                          // T1
    analyzer_detected_at: analyzerDetectedAt,
    source_to_analyzer_ms: Number.isFinite(srcMs) ? analyzerDetectedAtMs - srcMs : null,    // T1-T0
    _last_signal_at_ms: finding._last_signal_at_ms,  // noi bo, khong dua vao output
  });
}

// ---------------- INCIDENT DEDUPE ----------------
const staticData = $getWorkflowStaticData('global');

if (staticData.incidentDedupeSchemaVersion !== 2) {
  staticData.lastDetection = { PORT_SCAN: {}, BRUTE_FORCE: {} };
  staticData.incidentDedupeSchemaVersion = 2;
}
staticData.lastDetection ||= { PORT_SCAN: {}, BRUTE_FORCE: {} };
for (const type of ['PORT_SCAN', 'BRUTE_FORCE']) {
  const cur = staticData.lastDetection[type];
  if (!cur || Array.isArray(cur) || typeof cur !== 'object') staticData.lastDetection[type] = {};
}
delete staticData.banned;

const newEvents = [];

for (const detection of detections) {
  const eventType = detection.event_type;
  const ip = detection.src_ip;
  const srcMs = Number(detection.source_event_at_ms);
  const quietMs = INCIDENT_QUIET_MS[eventType] || 60000;

  let lastSignalAtMs = Number(detection._last_signal_at_ms);
  if (!Number.isFinite(lastSignalAtMs)) lastSignalAtMs = Number.isFinite(srcMs) ? srcMs : analyzerDetectedAtMs;

  staticData.lastDetection[eventType] ||= {};
  const previous = staticData.lastDetection[eventType][ip];

  let sameIncident = false;

  if (previous && typeof previous === 'object') {
    const prevSignalMs = Number(previous.last_signal_at_ms);
    const prevSeenMs = Number(previous.last_seen_at_ms);

    // Lop 1 - theo timestamp trong log
    if (Number.isFinite(prevSignalMs) && (lastSignalAtMs - prevSignalMs) <= quietMs) sameIncident = true;
    // Lop 2 - theo wall-clock analyzer (chong timestamp log lech)
    if (!sameIncident && Number.isFinite(prevSeenMs) && (analyzerDetectedAtMs - prevSeenMs) <= quietMs) sameIncident = true;
  }

  // Cung incident: KHONG tao event_id / BanIP / BanEvent / Audit / Ansible moi
  if (sameIncident) {
    const prevSignalMs = Number(previous.last_signal_at_ms);
    staticData.lastDetection[eventType][ip] = {
      ...previous,
      last_signal_at_ms: Number.isFinite(prevSignalMs) ? Math.max(prevSignalMs, lastSignalAtMs) : lastSignalAtMs,
      last_seen_at_ms: analyzerDetectedAtMs,
    };
    continue;
  }

  // Incident moi
  const randomPart = Math.random().toString(36).slice(2, 8).toUpperCase();
  const eventId = `${EVENT_PREFIX_MAP[eventType] || 'EVENT'}-${analyzerDetectedAtMs}-${randomPart}`;

  staticData.lastDetection[eventType][ip] = {
    event_id: eventId,
    first_detected_at_ms: analyzerDetectedAtMs,
    last_seen_at_ms: analyzerDetectedAtMs,
    last_signal_at_ms: lastSignalAtMs,
  };

  newEvents.push({
    ...detection,
    event_id: eventId,
    scenario: SCENARIO_MAP[eventType],
    ban_file: BAN_FILE_MAP[eventType],
    event_queue_file: EVENT_FILE_MAP[eventType],
  });
}

// ---------------- OUTPUT ----------------
const eventsByFile = {};
for (const event of newEvents) (eventsByFile[event.ban_file] ||= []).push(event);

function baseRecord(item) {
  return {
    schema_version: 1,
    event_id: item.event_id,
    scenario: item.scenario,
    src_ip: item.src_ip,
    event_type: item.event_type,
    metric: item.metric,
    source_event_at_ms: item.source_event_at_ms,
    source_event_at: item.source_event_at,
    analyzer_detected_at_ms: item.analyzer_detected_at_ms,
    analyzer_detected_at: item.analyzer_detected_at,
    source_to_analyzer_ms: item.source_to_analyzer_ms,
  };
}

const output = [];

for (const [banFile, items] of Object.entries(eventsByFile)) {
  output.push({
    json: {
      item_type: 'ban',
      ban_file: banFile,
      event_queue_file: items[0].event_queue_file,
      ips: items.map(i => i.src_ip),
      ban_content: items.map(i => i.src_ip).join('\n') + '\n',
      event_content: items.map(i => JSON.stringify({ ...baseRecord(i), attack_type: i.event_type, status: 'detected' })).join('\n') + '\n',
      audit_content: items.map(i => JSON.stringify({ ...baseRecord(i), record_type: 'security_detection' })).join('\n') + '\n',
      count: items.length,
    },
  });
}

if (dhcpLines.length > 0) {
  output.push({ json: { item_type: 'dhcp_batch', dhcp_content: dhcpLines.join('\n') + '\n', dhcp_count: dhcpLines.length } });
}

if (output.length === 0) {
  return [{
    json: {
      no_new_ban: true,
      reason: detections.length > 0 ? 'DETECTION_ALREADY_PROCESSED' : 'NO_ATTACK_DETECTED',
      scanned: rawLines.length,
      total_detections: detections.length,
      new_events: newEvents.length,
      deduped_count: detections.length - newEvents.length,
      detected_ips: detections.map(d => d.src_ip),
      detected_types: detections.map(d => d.event_type),
      analyzer_checked_at_ms: analyzerDetectedAtMs,
      analyzer_checked_at: analyzerDetectedAt,
    },
  }];
}

return output;
